#include <vector>
#include <algorithm>

using namespace std;

/**
 * Problem: LeetCode 1872 - Stone Game VIII
 * Difficulty: Hard
 * Language: C++
 * Author: CodeByTushu
 */
class Solution {
public:
    int stoneGameVIII(vector<int>& stones) {
        int n = stones.size();
        vector<long long> prefix(n);
        prefix[0] = stones[0];
        for (int i = 1; i < n; ++i) {
            prefix[i] = prefix[i - 1] + stones[i];
        }

        // dp represents the best score difference achievable starting from index i
        long long dp = prefix[n - 1];
        for (int i = n - 2; i >= 1; --i) {
            dp = max(dp, prefix[i] - dp);
        }

        return static_cast<int>(dp);
    }
};

